using System;

public class Person {
    public string Name { get; set; }
}

public class Teacher : Person { }

public class C {
    public void M(Person p) {
        switch (p) {
            case Teacher { Name: var name }:
                Console.WriteLine($"Hello teacher { name}!");
            break;
            case Person { Name: var name }:
                Console.WriteLine($"Hello { name}!");
            break;
        }
    }
}
